  BOOK ||--o{ COPY : "所蔵"
  BOOK }o--o{ AUTHOR : "著者"
  COPY ||--o{ LOAN : "貸出"
  MEMBER ||--o{ LOAN : "借りる"
  MEMBER ||--o{ RESERVATION : "予約"
  BOOK ||--o{ RESERVATION : "予約対象"
  BOOK {
